#!/usr/bin/env python3
"""Exact builtin kernel axiom inventory; not a complete source or full gate."""
import json
from pathlib import Path
import re
import sys
PINS = {'Solidity.Backend.InternalFlow.LocalStoreFlow.StmtPlan.sound': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LocalStoreFlow.ProgPlan.sound': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LocalStoreFlow.ProgPlan.plain_slot': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LocalStoreFlow.ProgPlan.fragile_slot': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LocalStoreFlow.program_statement_frames': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.source_run': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.alias_frame': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.selected_guard': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.complete_source': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.protected_unwritten': ['Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.captured_locals': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.original_guard_rejects': ['propext'], 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.actual_endpoint': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.written_scalar_guard': ['Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.wrong_old_contents': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.wrong_new_alias': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.private_marker_nonescape': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.wrong_persistent_value': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.skipped_reverts': ['Classical.choice', 'Quot.sound', 'propext']}
NAMES = ['Solidity.Backend.InternalFlow.LocalStoreFlow.StmtPlan.sound', 'Solidity.Backend.InternalFlow.LocalStoreFlow.ProgPlan.sound', 'Solidity.Backend.InternalFlow.LocalStoreFlow.ProgPlan.plain_slot', 'Solidity.Backend.InternalFlow.LocalStoreFlow.ProgPlan.fragile_slot', 'Solidity.Backend.InternalFlow.LocalStoreFlow.program_statement_frames', 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.source_run', 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.alias_frame', 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.selected_guard', 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.complete_source', 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.protected_unwritten', 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.captured_locals', 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.original_guard_rejects', 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.actual_endpoint', 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.written_scalar_guard', 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.wrong_old_contents', 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.wrong_new_alias', 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.private_marker_nonescape', 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.wrong_persistent_value', 'Solidity.Backend.InternalFlow.FragileReturnChecks.ScopedAlias.skipped_reverts']
def check(text):
    if re.search(r"(?:^|\n).*?(?:error:|error\(|sorryAx)",text):
        raise ValueError("Lean diagnostic or untrusted axiom")
    rows = [(n,sorted(x.strip()for x in a.split(',')if x.strip()))
        for n,a in re.findall(r"'([^']+)' (?:depends on axioms:\s*\[([^\]]*)\]|does not depend on any axioms)",text)]
    if rows != [(n,PINS[n])for n in NAMES]:
        raise ValueError("missing, extra, duplicate, reordered or changed axiom report")
    return len(rows)
log = Path(sys.argv[1]).read_text()
print(json.dumps({'status':'pass','reports':check(log)}))
